{
  "status": "SUPPORTED",
  "task_summary": "Identify fastening components, apply them to a target on the workbench, and leave the tool there.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "the specific location or object on the workbench that needs to be fastened",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "assembly_part",
          "base_plate",
          "fixture"
        ],
        "required_properties": [
          "has_fastening_points",
          "is_at_marked_location"
        ]
      },
      {
        "id": "fastening_components",
        "entity_kind": "OBJECT",
        "function": "physical items required to secure the target (screws, bolts, etc.)",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "fastener"
        ],
        "required_properties": [
          "compatible_with_target"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "implement used to apply the fastening components",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "wrench",
          "screwdriver",
          "hammer"
        ],
        "required_properties": [
          "can_apply_force"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "the surface where the task occurs and where tools must be returned",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "bench"
        ],
        "required_properties": [
          "is_horizontal_surface"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_with",
        "relation": "fastening_components must fit or suit fastening_target",
        "participant_roles": [
          "fastening_components",
          "fastening_target"
        ]
      ,
      "required": true
      },
      {
        "id": "applied_to",
        "relation": "fastening_tool acts upon fastening_target using fastening_components",
        "participant_roles": [
          "fastening_tool",
          "fastening_components",
          "fastening_target"
        ]
      ,
      "required": true
      },
      {
        "id": "secured_to",
        "relation": "fastening_components are physically attached to fastening_target",
        "participant_roles": [
          "fastening_components",
          "fastening_target"
        ]
      ,
      "required": true
      },
      {
        "id": "left_on",
        "relation": "fastening_tool must end up resting on workbench",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "search for and select appropriate fastening_components",
        "participant_roles": [
          "fastening_components"
        ,
        "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "apply_fastening",
        "operation": "use fastening_tool to attach fastening_components to fastening_target",
        "participant_roles": [
          "fastening_tool",
          "fastening_components",
          "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "move fastening_tool to rest on workbench",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "yellow_grey_object_on_mat",
          "visual_description": "A yellow and grey rectangular object sitting on a black mat on the workbench surface."
        }
      ],
      "fastening_components": [
        {
          "label": "yellow_grey_object_on_mat",
          "visual_description": "The object on the mat might contain the components or be the target itself."
        }
      ],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden table with drawers and cabinets nearby."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "tall_cabinet",
        "label": "blue_cabinet_door",
        "visual_description": "A tall blue cabinet standing against the wall next to the workbench.",
        "reason": "Likely contains stored tools or components."
      },
      {
        "id": "left_drawer",
        "label": "left_table_drawer",
        "visual_description": "A blue drawer located under the left side of the workbench.",
        "reason": "Likely contains small parts or tools."
      },
      {
        "id": "right_drawer",
        "label": "right_table_drawer",
        "visual_description": "A blue drawer located under the right side of the workbench.",
        "reason": "Likely contains small parts or tools."
      }
    ],
    "inspection_order": [
      "tall_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
